interface.definition:
a!localVariables(
  {

    /* ── TITLE BAR ── */
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_sideBySideLayout"(
          alignVertical: "MIDDLE",
          items: {
            /* Icon */
            #"SYSTEM_SYSRULES_sideBySideItem"(
              width: "MINIMIZE",
              item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                marginBelow: "NONE",
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextIcon"(
                    icon: "users",
                    size: "MEDIUM_PLUS"
                  )
                }
              )
            ),
            /* Page Title */
            #"SYSTEM_SYSRULES_sideBySideItem"(
              item: #"SYSTEM_SYSRULES_headingField"(
                marginBelow: "NONE",
                text: "Team Management",
                fontWeight: "SEMI_BOLD",
                size: "MEDIUM",
                headingTag: "H1"
              )
            ),
            /* Create Team Action — System Admin only */
            #"SYSTEM_SYSRULES_sideBySideItem"(
              width: "MINIMIZE",
              item: #"SYSTEM_SYSRULES_recordActionField_v1"(
                actions: #"SYSTEM_SYSRULES_recordActionItem"(
                  action: #"urn:appian:record-action:v1:bb51e73c-01e7-4e73-8a7b-4187491dde54/43401982-d7ea-4381-8d1e-ece4f6840a0e"
                ),
                style: "CALL_TO_ACTION",
                align: "END",
                showWhen: #"urn:appian:function:v1:a:isusermemberofgroup?okey=a!isUserMemberOfGroup"(
                  username: loggedInUser(),
                  groups: #"_a-0000eef8-4604-8000-9e54-011c48011c48_1189961"
                )
              )
            )
          }
        )
      },
      height: "AUTO",
      style: "ACCENT",
      padding: "STANDARD",
      marginBelow: "NONE",
      showBorder: false
    ),
    /* ── CONTENT AREA ── */
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"_a-0000eef8-4604-8000-9e54-011c48011c48_1132937"()
      },
      height: "AUTO",
      style: "NONE",
      shape: "SEMI_ROUNDED",
      padding: "STANDARD",
      marginBelow: "STANDARD",
      showBorder: false,
      showShadow: true
    )
  }
)
